        station.start(
            onReading: { temperature in
                continuation.yield(temperature)
            },
            onFinish: {
                continuation.finish()
            }
        )
    }
}

// 2. Объяви модель виджета LiveTemperatureModel на главном акторе
@MainActor
final class LiveTemperatureModel {
